-- Curation priorities (sent by the curators on 2026-10-29).
-- P0 and P1 (642 questions) were split among three people and are assigned
-- now: Pessoa 1 = Patrick, Pessoa 2 = Thierry, Pessoa 3 = Lucas.
-- P2 and P3 (12,961) come in random order and are only planned: the future
-- owner rotates Patrick, Thierry, Lucas along that order; nothing is assigned.
begin;

create table public.curation_priorities (
  question_id bigint primary key,
  priority text not null check (priority in ('P0','P1','P2','P3')),
  planned_curator text not null,
  rank integer not null
);
alter table public.curation_priorities enable row level security;
revoke all on public.curation_priorities from public,anon,authenticated;

