-- Assign P0/P1 to their curator; bump the version and log one event so every
-- open app picks the change up through curation_sync.
do $$
declare ids bigint[];
begin
  with assigned as (
    update public.curation_questions q
       set responsible_id=p.planned_curator, version=q.version+1
      from public.curation_priorities p
     where p.question_id=q.question_id and p.priority in ('P0','P1')
       and q.responsible_id is distinct from p.planned_curator
    returning q.question_id
  ) select array_agg(question_id) into ids from assigned;
  if ids is not null then
    insert into curation_private.events(actor,action,question_ids,changes)
    values(null,'priority_assign',ids,jsonb_build_object('source','20261029120000_curation_priorities'));
  end if;
  raise notice 'P0/P1 atribuídas: %; IDs da lista que não existem no banco: %',
    coalesce(cardinality(ids),0),
    (select count(*) from public.curation_priorities p where not exists(select 1 from public.curation_questions q where q.question_id=p.question_id));
end $$;

-- Deadline for P0/P1, before the deadline of the whole base.
alter table curation_private.goals add column deadline_priority date;

create or replace function public.curation_priorities() returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare result jsonb;
begin
  if not public.curation_is_member() then raise exception 'Curador não autorizado'; end if;
  -- Compact: ids per priority (in rank order) and per planned curator.
  select jsonb_build_object(
    'priority',(select jsonb_object_agg(priority,ids) from (select priority,jsonb_agg(question_id::text order by planned_curator,rank) ids from public.curation_priorities group by priority) x),
    'planned',(select jsonb_object_agg(planned_curator,ids) from (select planned_curator,jsonb_agg(question_id::text order by priority,rank) ids from public.curation_priorities group by planned_curator) y)
  ) into result;
  return result;
end $$;

create or replace function public.curation_activity(p_days integer default 90) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare days integer:=least(greatest(coalesce(p_days,90),7),365); result jsonb;
begin
  if not public.curation_is_member() then raise exception 'Curador não autorizado'; end if;
  with audits as (
    select m.curator_id, (e.created_at at time zone 'America/Sao_Paulo')::date as day, q as question_id
    from curation_private.events e
    join public.curation_members m on m.user_id=e.actor
    cross join lateral unnest(e.question_ids) q
    where e.action in ('status','review','save')
  ), daily as (
    select day, curator_id, count(distinct question_id) audited from audits
    where day > (now() at time zone 'America/Sao_Paulo')::date - days
    group by day, curator_id
  ), totals as (
    select curator_id, count(distinct question_id) audited from audits group by curator_id
  )
  select jsonb_build_object(
    'today',(now() at time zone 'America/Sao_Paulo')::date,
    'daily',coalesce((select jsonb_agg(jsonb_build_object('day',day,'curator',curator_id,'audited',audited) order by day) from daily),'[]'::jsonb),
    'totals',coalesce((select jsonb_object_agg(curator_id,audited) from totals),'{}'::jsonb),
    'goals',(select jsonb_build_object('daily',daily,'deadline',deadline,'deadline_priority',deadline_priority,'updated_by',updated_by,'updated_at',updated_at) from curation_private.goals)
  ) into result;
  return result;
end $$;

drop function public.curation_set_goals(jsonb,date);
create function public.curation_set_goals(p_daily jsonb, p_deadline date, p_deadline_priority date default null) returns jsonb
language plpgsql security definer set search_path='' as $$
declare member public.curation_members; k text; v jsonb;
begin
  select * into member from public.curation_members where user_id=curation_private.actor() and active;
  if member.user_id is null then raise exception 'Curador não autorizado'; end if;
  if jsonb_typeof(p_daily) is distinct from 'object' then raise exception 'Metas inválidas'; end if;
  for k,v in select * from jsonb_each(p_daily) loop
    if not exists(select 1 from public.curation_members where curator_id=k) then raise exception 'Curador desconhecido: %',k; end if;
    if jsonb_typeof(v)<>'number' or (v::text)::numeric<0 or (v::text)::numeric>1000 or (v::text)::numeric<>trunc((v::text)::numeric) then raise exception 'Meta diária deve ser um número inteiro de 0 a 1000'; end if;
  end loop;
  if p_deadline_priority is not null and p_deadline is not null and p_deadline_priority>p_deadline then raise exception 'O prazo de P0/P1 deve vir antes do prazo do banco'; end if;
  update curation_private.goals set daily=p_daily,deadline=p_deadline,deadline_priority=p_deadline_priority,updated_by=member.name,updated_at=now() where id;
  return (select jsonb_build_object('daily',daily,'deadline',deadline,'deadline_priority',deadline_priority,'updated_by',updated_by,'updated_at',updated_at) from curation_private.goals);
end $$;

revoke all on function public.curation_priorities(),public.curation_activity(integer),public.curation_set_goals(jsonb,date,date) from public;
-- The app calls with the anon key and proves membership with x-apex-session.
grant execute on function public.curation_priorities(),public.curation_activity(integer),public.curation_set_goals(jsonb,date,date) to anon,authenticated;
commit;
